-- create_products: forward migration.
-- Released migrations are immutable; change the schema with a new migration.

CREATE TABLE products (
    -- UUIDv7 generated by the application; time-ordered, so it doubles as
    -- the keyset pagination cursor (primary-key index, ORDER BY id DESC).
    id          uuid        PRIMARY KEY,
    sku         text        NOT NULL,
    name        text        NOT NULL,
    price_cents bigint      NOT NULL,
    currency    text        NOT NULL,
    version     bigint      NOT NULL DEFAULT 1,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    -- The repository maps violations of this constraint to `sku_taken`.
    CONSTRAINT products_sku_key UNIQUE (sku),
    -- Defense in depth: mirror the domain value objects.
    CONSTRAINT products_sku_format CHECK (sku ~ '^[A-Z0-9-]{3,32}$'),
    CONSTRAINT products_name_length CHECK (char_length(name) BETWEEN 1 AND 120),
    CONSTRAINT products_price_cents_non_negative CHECK (price_cents >= 0),
    CONSTRAINT products_currency_format CHECK (currency ~ '^[A-Z]{3}$'),
    CONSTRAINT products_version_positive CHECK (version >= 1)
);
